// English dictionary for the game (language switch, src/game/lang.ts).
// Nouns only, in parity with the Russian dictionary: WordNet 3.1 noun lemmas
// (https://wordnetcode.princeton.edu/, dict/index.noun) kept if present in any
// of three common-word lists: dolph/dictionary popular.txt, OpenSubtitles 2018
// en_50k (hermitdave/FrequencyWords), google-10000-english (first20hours) —
// popular.txt alone, the previous filter, dropped everyday nouns WordNet knows
// (soundtrack, wifi, internet, email, tv, pc, dna, fbi, ok). Proper nouns and
// abbreviations are dropped by the case of their occurrences in data.noun: a
// lemma that never appears lowercase is not a plain word — it is a name
// (Abraham, Aberdeen, McDonald) or an abbreviation (bk, ghz, gsr, jfk) — and
// is kept only on the KEEP whitelist of widely known abbreviations below
// (atm, dna, fbi, gps, kgb, pc, wifi, www). The DROP blocklist below removes
// the abbreviation- and symbol-junk that slipped through lowercase occurrences
// in WordNet glosses (kg, lb, mm, ph, hr, db) and obscure letter-words
// (aa, ut, os) — mostly two-letter ones. Lowercase a-z, length 2 and up (the
// original capped words at 10 letters; the trie has no such limit).
// Regenerate (bash; reading files instead of piping into node's stdin — on
// Windows the pipe mangles UTF-8; then re-add this header in front of the
// output):
//   curl -sL -o popular.txt https://raw.githubusercontent.com/dolph/dictionary/master/popular.txt
//   curl -sL -o en-50k.txt https://raw.githubusercontent.com/hermitdave/FrequencyWords/master/content/2018/en/en_50k.txt
//   curl -sL -o google-10k.txt https://raw.githubusercontent.com/first20hours/google-10000-english/master/google-10000-english-no-swears.txt
//   curl -sL -o wordnet31.zip https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/wordnet31.zip
//   unzip -j -o wordnet31.zip 'wordnet31/index.noun' 'wordnet31/data.noun' -d dict
//   node -e "const fs=require('fs');const load=f=>new Set(fs.readFileSync(f,'utf8').split(/\r?\n/).filter(Boolean).map(l=>l.trim()));const popular=load('popular.txt'),g=load('google-10k.txt');const sub=new Set([...load('en-50k.txt')].map(l=>l.split(' ')[0]));const low=new Set();for(const l of fs.readFileSync('dict/data.noun','utf8').split(/\r?\n/)){if(!l||l[0]===' ')continue;const t=l.split(' | ')[0].split(' ');const n=parseInt(t[3],16);for(let i=0;i<n;i++){const w=t[4+i*2];if(/^[a-z]/.test(w))low.add(w.toLowerCase());}}const KEEP=new Set('abc aids atm cdc ceo cia cpu cpr dna dvd eu fbi fcc fda faa ftp gdp gmt gps gui hiv http html icu imf iq kgb lcd led mba mri mvp nasa nato ngo ok pc pbs phd sos suv ufo uk un unix url usa us ussr unicef vip vcr who wto www wifi'.split(' '));const DROP=new Set('aa ab ai ar at bm cc cd cl cm db dg dl dm eq ev ft gm he hl hm hr kb kc kg ki km kt kw lb li lm mg ml mm ms mv ng nm os pe ph si sr te ut yr'.split(' '));const out=[];const seen=new Set();for(const l of fs.readFileSync('dict/index.noun','utf8').split(/\r?\n/)){const w=l.split(' ')[0];if(/^[a-z]{2,}$/.test(w)&&!seen.has(w)&&!DROP.has(w)&&(popular.has(w)||g.has(w)||sub.has(w))&&(low.has(w)||KEEP.has(w))){seen.add(w);out.push(w);}}out.sort();fs.writeFileSync('dictionary-en.ts','export const dictionary: string[] = '+JSON.stringify(out)+';\n');"
